import * as React from "react";
import "./CircleIcon.scss";
import clsx from "clsx";
import { MpaIcon } from "../../icon";

export type CircleIconStatus = "success" | "warning";

export interface CircleIconProps {
  status?: CircleIconStatus;
}

const CircleIcon = ({ status }: CircleIconProps) => {
  let iconName = "CircleCheck_Filled";
  if (status === "warning") {
    iconName = "AlertCircle_Filled";
  }

  return (
    <div
      className={clsx("circle-icon-container", {
        "circle-icon-success": status === "success",
        "circle-icon-warning": status === "warning",
      })}
    >
      <MpaIcon iconName={iconName} />
    </div>
  );
};

export default CircleIcon;
